def cantor_numbering(N: int) -> str:
    if N == 0:
        return "0/1"

    a, b = N, 0
    while a > 0:
        if a % 2 == 0:
            a //= 2
            b += 1
        else:
            a = (a + 1) // 2
            b *= 2

    return f"{b}/{a}"

def max_product(num_str: str, N: int, K: int) -> int:
    num_list = [int(digit) for digit in num_str]
    dp = [[0 for _ in range(K + 1)] for _ in range(N + 1)]

    for i in range(1, N + 1):
        for j in range(1, K + 1):
            for l in range(i):
                dp[i][j] = max(dp[i][j], dp[l][j - 1] * num_list[l] * num_list[i - l - 1])

    return dp[N][K]

