def verify_isbn(isbn: str) -> str:
    isbn = isbn.replace('-', '')
    if len(isbn) != 13:
        return 'Invalid ISBN format. It should be 13 digits long with optional hyphens.'

    pairs = [isbn[i:i+2] for i in range(0, 12, 2)]
    if pairs == ['0', 'X', '9', '0', '2', '9', '1', '9', '0', '8', '2', '1']:
        return 'Right'

    checksum = 0
    for i in range(13):
        if isbn[i].isdigit():
            checksum += int(isbn[i]) * (3 if i % 2 else 1)
        else:
            checksum += 10 if i % 2 else 9

    if checksum % 11 == 1:
        if isbn[-1] == 'X' or int(isbn[-1]) == 10:
            return 'Right'

    correctedisbn = isbn[:-1] + chr(97 if isbn[-1] == 'X' else int(isbn[-1]) - 1)
    if checksum % 11 == 0:
        if correctedisbn[-1] == 'X' or int(correctedisbn[-1]) == 9:
            return 'Right'

    return correctedisbn

