def count_passing_ways(n: int, m: int) -> int:
    def binomial_coefficient(n: int, k: int) -> int:
        result = 1
        for i in range(k):
            result *= (n - i)
            result //= (i + 1)
        return result

    if m == 0 or n == 1:
        return 1

    dp = [[0 for _ in range(n)] for _ in range(m + 1)]
    for i in range(n):
        dp[0][i] = 1

    for i in range(1, m + 1):
        for j in range(0, n):
            dp[i][j] = dp[i - 1][(j - 2 + n) % n] + dp[i - 1][(j + 2) % n]

    return binomial_coefficient(m, 1) * dp[m - 1][(m // 2 - 1 + n) % n]

