def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    def format_coefficient(coeff: int):
        if coeff == 0:
            return ''
        sign = '-' if coeff < 0 else '+'
        magnitude = abs(coeff)
        if magnitude == 1:
            return sign + 'x' if sign else ''  # Handle constant term as only x^0 or just x
        elif magnitude == coeffs[-1]:
            return sign + f'x^{magnitude - 1}'  # Handle constant term as only x^0 or just x
        else:
            return sign + f'{magnitude}x^{magnitude - 1}'

    result = []
    for i, coeff in enumerate(coeffs, start=1):
        if coeff != 0:
            result.append(format_coefficient(coeff))
            if i < n:
                result.append('-' if i != n else '')
    return ''.join(result)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for i, e in enumerate(encoded):
        if e not in original:
            return "Failed"
        mapping[e] = original[i]

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def count_partitions(n: int, k: int, x: int) -> int:
    z = n - (k - 1) * x  # Adjust so the minimum part size is x
    s = k * (k + 1) // 2  # Maximum number of parts even if k = n
    if z % (k - 1) != 0:
        if z // (k - 1) < x:
            return 0
        elif z // (k - 1) > x:
            return 0
        else:
            return s + (z // (k - 1) - x + 2)
    else:
        return s

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n < 1 or last < 1 or n > last**0.5:
        return 0

    if (n, last) in memo:
        return memo[(n, last)]

    count = 0
    if n == last:
        count += 1

    for new in range(n + 1, last + 1):
        count += count_sequences(n, new, memo)

    memo[(n, last)] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    quotient = y0 // x0
    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if math.gcd(a, b) == 1:  # Check if a and b are co-prime
