def bfs(start, target, rules, max_steps):
    if start == target:
        return 0

    queue = Queue()
    queue.put((start, 0))
    visited = set()

    while not queue.empty() and queue.qsize() <= max_steps:
        current, steps = queue.get()

        if current in visited:
            continue
        visited.add(current)

        if current == target:
            return steps

        for neighbor in generate_neighbors(current, rules):
            if neighbor not in visited:
                queue.put((neighbor, steps + 1))

    return "NO ANSWER!"

