def catalan_number(n):
    # Base case
    if n <= 1:
        return 1

    # Initialize the first two Catalan numbers
    catalan = [0] * (n + 1)
    catalan[0], catalan[1] = 1, 1

    # Compute the Catalan numbers iteratively
    for i in range(2, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - 1 - j]

    return catalan[n]

