def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    n = len(herbs)

    # Create a 2D array to store maximum value that can be obtained with at most i units of time
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Fill the dp table
    for i in range(1, M + 1):
        for j in range(1, T + 1):
            time, value = herbs[i - 1]
            if time <= j:
                dp[i][j] = max(value + dp[i - 1][j - time], dp[i - 1][j])
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[M][T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a 2D array dp where dp[i][j] represents the maximum volume that can be occupied
    # by the first i items with a subset of the first j volumes
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill dp table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            if volumes[j - 1] <= i:
                dp[i][j] = max(dp[i][j - 1], dp[i - volumes[j - 1]][j - 1] + volumes[j - 1])
            else:
                dp[i][j] = dp[i][j - 1]

    # The minimum remaining space is the difference between the box's total capacity and the maximum occupied volume
    return V - dp[V][n]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m+1) for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, m+1):
            if j <= a[i-1]:
                dp[i][j] = sum(dp[i-1][k] for k in range(j+1)) % MOD
            else:
                dp[i][j] = dp[i-1][j] % MOD
    return dp[n][m] % MOD

def vigenere_decrypt(key: str, ciphertext: str) -> str:
    # Convert key and ciphertext to uppercase
    key = key.upper()
    ciphertext = ciphertext.upper()

    # Determine the length of the key
    key_length = len(key)

    #.Replace spaces in the key and ciphertext with the first letter of the key
    key = key.replace(" ", key[0])
    ciphertext = ciphertext.replace(" ", key[0])

    # Create a mapping from each lowercase alphabetic character to its corresponding index
    def char_to_index(char):
        return ord(char) - ord('A')

    # Create a mapping from each index to its corresponding lowercase alphabetic character
    def index_to_char(index):
        return chr(index + ord('A'))

    # Perform the Vigenère decryption
    decrypted = ""
    for i, char in enumerate(ciphertext):
        if char.isalpha():
            index = char_to_index(char)
            shift = char_to_index(key[i % key_length])
            decrypted += index_to_char((index - shift + 26) % 26)
        else:
            decrypted += char

    return decrypted

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness_index = 0
    max_unhappiness = 0

    for day, (school_hours, extra_hours) in enumerate(schedule):
        # Calculate total hours
        total_hours = school_hours + extra_hours
        # Check if total hours exceed the threshold
        if total_hours > 8:
            happiness = 8 - total_hours
            if happiness > max_unhappiness:
                max_unhappiness = happiness
                max_unhappiness_index = day

    return max_unhappiness_index + 1 if max_unhappiness_index != 0 else 0

